// Reading task state straight out of the tasks repo's SQLite database.
//
// The tasks CLI owns one DB and publishes index.json / events.json from it on
// every mutation. This server used to read only those files, which made the UI
// a derivative of a derivative: a `done` that landed in the DB but whose
// republish went somewhere else (a worktree copy), or which raced a reader, or
// which the operator ran through a path that skipped the publish, left ringo
// showing a story as still open long after the CLI said done. The observable
// symptom was always the same and always confusing — the agent reports done,
// `tasks show` agrees, the page disagrees.
//
// So the DB is the source of truth here too. index.json stays as the fallback
// for anything that has no DB (tests with a fixture directory, a checkout that
// predates the SQLite cutover), which also keeps the shapes below honest: they
// must reproduce readmodel.ts exactly, because the same structs are filled
// either way.

// tasksDBPath returns the SQLite file the tasks CLI writes.
//
// TASKS_DB overrides, matching the CLI's own env. Otherwise it resolves the
// same way src/db-path.ts does: the DB lives in the GIT COMMON DIR, not the
// working tree, because that is the one directory every worktree, the CLI and
// this container already agree on.
func tasksDBPath(tasksDir string) string {
	if v := strings.TrimSpace(os.Getenv("TASKS_DB")); v != "" {
		return v
	}
	return filepath.Join(gitCommonDir(tasksDir), "tasks.db")
}

// gitCommonDir resolves dir/.git to the shared common dir. A worktree's `.git`
// is a file pointing at <common>/worktrees/<name>, which carries a `commondir`
// pointer back; the main checkout's is the directory itself. Falls back to
// dir/.git on any surprise, so a caller still gets a plausible path to report.
func gitCommonDir(dir string) string {
	dotgit := filepath.Join(dir, ".git")
	info, err := os.Stat(dotgit)
	if err != nil {
		return dotgit
	}
	if info.IsDir() {
		return dotgit
	}
	raw, err := os.ReadFile(dotgit)
	if err != nil {
		return dotgit
	}
	gitdir := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(string(raw)), "gitdir:"))
	if !filepath.IsAbs(gitdir) {
		gitdir = filepath.Join(dir, gitdir)
	}
	if common, err := os.ReadFile(filepath.Join(gitdir, "commondir")); err == nil {
		rel := strings.TrimSpace(string(common))
		if !filepath.IsAbs(rel) {
			rel = filepath.Join(gitdir, rel)
		}
		return filepath.Clean(rel)
	}
	return gitdir
}

// Connections are cached per path: opening a SQLite file is cheap but not free,
// and the story/backlog pages hit this on every request. database/sql pools
// underneath, so one handle serves concurrent readers.
var (
	tasksDBMu    sync.Mutex
	tasksDBConns = map[string]*sql.DB{}
)

// openTasksDB returns a read-only handle to the tasks DB at path.
//
// Read-only is a hard requirement, not a precaution: the CLI is the only writer
// and a second writer on a WAL database is how you get a wedged lock during a
// spawn. busy_timeout covers the moment a mutation holds the write lock.
func openTasksDB(path string) (*sql.DB, error) {
	tasksDBMu.Lock()
	defer tasksDBMu.Unlock()
	if db, ok := tasksDBConns[path]; ok {
		return db, nil
	}
	db, err := sql.Open("sqlite", "file:"+path+"?mode=ro&_pragma=busy_timeout(5000)")
	if err != nil {
		return nil, fmt.Errorf("open tasks db %s: %w", path, err)
	}
	if err := db.Ping(); err != nil {
		db.Close()
		return nil, fmt.Errorf("open tasks db %s: %w", path, err)
	}
	tasksDBConns[path] = db
	return db, nil
}

// loadTaskIndex returns the task index for tasksDir, preferring the database.
//
// The JSON fallback is not a fast path or a cache — it is what a directory
// without a DB gets. When the DB is present and unreadable that is worth
// knowing about, so the error is logged before falling back rather than
// swallowed into a silently stale page.
func loadTaskIndex(tasksDir string) (*taskIndex, error) {
	path := tasksDBPath(tasksDir)
	if _, err := os.Stat(path); err == nil {
		idx, err := loadTaskIndexFromDB(path)
		if err == nil {
			return idx, nil
		}
		logTasksDBFallback("index", path, err)
	}
	return loadTaskIndexFromJSON(tasksDir)
}

// logTasksDBFallback reports a DB read that fell back to JSON, once per
// distinct message. Every page on the dashboard loads the index, so an
// unthrottled log here turns one bad permission bit into a flood.
var (
	tasksDBLogMu   sync.Mutex
	tasksDBLogSeen = map[string]bool{}
)

func logTasksDBFallback(what, path string, err error) {
	msg := fmt.Sprintf("tasks %s: %s unreadable, falling back to JSON: %v", what, path, err)
	tasksDBLogMu.Lock()
	seen := tasksDBLogSeen[msg]
	tasksDBLogSeen[msg] = true
	tasksDBLogMu.Unlock()
	if !seen {
		log.Print(msg)
	}
}

// loadTaskIndexFromJSON is the pre-DB path, unchanged.
func loadTaskIndexFromJSON(tasksDir string) (*taskIndex, error) {
	data, err := os.ReadFile(filepath.Join(tasksDir, "index.json"))
	if err != nil {
		return nil, fmt.Errorf("read tasks index: %w", err)
	}
	var idx taskIndex
	if err := json.Unmarshal(data, &idx); err != nil {
		return nil, fmt.Errorf("parse tasks index: %w", err)
	}
	return &idx, nil
}

// priorityUnset is the sort key an unprioritised story gets, mirroring
// readmodel.ts's PRIORITY_UNSET. It only orders; it is never emitted.
const priorityUnset = 1_000_000

// loadTaskIndexFromDB rebuilds the same structure index.json carries.
//
// This is a port of readmodel.ts buildIndex, and the two must not drift. The
// load-bearing parts, in the order they bite:
//
//	ordering    RFCs by id, stories by (priority, id) — the spawn loop consumes
//	            index order, so the sort IS part of the ready-queue ranking.
//	status      the parent-RFC override: a `ready` story under a non-active RFC
//	            is downgraded to `draft` at emit time so nothing can present it
//	            as claimable. Stored status is the AUTHORED one.
//	dates       index.json carried ISO midnight (js-yaml parsed frontmatter
//	            dates into Dates), so a date-only column becomes <date>T00:00:00Z.
//
// Six flat queries, grouped in Go: an N+1 over 7k stories would be seconds.
func loadTaskIndexFromDB(path string) (*taskIndex, error) {
	db, err := openTasksDB(path)
	if err != nil {
		return nil, err
	}

	deps, err := tasksGroupBy(db, "SELECT story_id, depends_on_id FROM story_deps ORDER BY rowid")
	if err != nil {
		return nil, err
	}
	rfcDeps, err := tasksGroupBy(db, "SELECT story_id, rfc_id FROM story_rfc_deps ORDER BY rowid")
	if err != nil {
		return nil, err
	}
	pkgs, err := tasksGroupBy(db, "SELECT story_id, package FROM story_packages ORDER BY rowid")
	if err != nil {
		return nil, err
	}

	idx := &taskIndex{}
	rfcStatus := map[string]string{}

	rfcRows, err := db.Query(`SELECT id, title, status, priority, owner, created_on, updated_on,
	                                 packages, clusters, superseded_by, related_rfcs, file_path
	                          FROM rfcs ORDER BY id`)
	if err != nil {
		return nil, fmt.Errorf("query rfcs: %w", err)
	}
	defer rfcRows.Close()
	for rfcRows.Next() {
		var (
			r                                                rfc
			title, status, owner, created, updated, filePath sql.NullString
			packages, clusters, supersededBy, relatedRFCs    sql.NullString
			priority                                         sql.NullInt64
		)
		if err := rfcRows.Scan(&r.ID, &title, &status, &priority, &owner, &created, &updated,
			&packages, &clusters, &supersededBy, &relatedRFCs, &filePath); err != nil {
			return nil, fmt.Errorf("scan rfc: %w", err)
		}
		r.Title = title.String
		r.Status = status.String
		r.Owner = owner.String
		r.Created = isoMidnight(created)
		r.Updated = isoMidnight(updated)
		r.Packages = parseJSONArray(packages)
		r.Clusters = parseJSONArray(clusters)
		r.RelatedRFCs = parseJSONArray(relatedRFCs)
		r.FilePath = filePath.String
		if supersededBy.Valid {
			v := supersededBy.String
			r.SupersededBy = &v
		}
		if priority.Valid {
			p := int(priority.Int64)
			r.Priority = &p
		}
		rfcStatus[r.ID] = r.Status
		idx.RFCs = append(idx.RFCs, r)
	}
	if err := rfcRows.Err(); err != nil {
		return nil, fmt.Errorf("read rfcs: %w", err)
	}

	storyRows, err := db.Query(`SELECT id, rfc_id, title, cluster, status, priority, est_loc,
	                                   updated_on, assignee, claim_at, pr, closed_reason, file_path
	                            FROM stories`)
	if err != nil {
		return nil, fmt.Errorf("query stories: %w", err)
	}
	defer storyRows.Close()
	sortKeys := map[string]int{}
	for storyRows.Next() {
		var (
			s                                         story
			rfcID, title, cluster, status, updated    sql.NullString
			assignee, claimAt, closedReason, filePath sql.NullString
			pr                                        sql.NullString
			priority, estLOC                          sql.NullInt64
		)
		if err := storyRows.Scan(&s.ID, &rfcID, &title, &cluster, &status, &priority, &estLOC,
			&updated, &assignee, &claimAt, &pr, &closedReason, &filePath); err != nil {
			return nil, fmt.Errorf("scan story: %w", err)
		}
		s.RFC = rfcID.String
		s.Title = title.String
		s.Cluster = cluster.String
		s.Status = effectiveStoryStatus(rfcStatus[s.RFC], status.String)
		s.Updated = isoMidnight(updated)
		s.Assignee = assignee.String
		s.Claim = claimAt.String
		s.ClosedReason = closedReason.String
		s.FilePath = filePath.String
		s.Packages = orEmpty(pkgs[s.ID])
		s.Deps = orEmpty(deps[s.ID])
		s.DepsRFC = orEmpty(rfcDeps[s.ID])
		s.EstLOC = int(estLOC.Int64)
		s.PRRepo, s.PR = scanPRRef(pr)
		key := priorityUnset
		if priority.Valid {
			p := int(priority.Int64)
			s.Priority = &p
			key = p
		}
		sortKeys[s.ID] = key
		idx.Stories = append(idx.Stories, s)
	}
	if err := storyRows.Err(); err != nil {
		return nil, fmt.Errorf("read stories: %w", err)
	}

	sort.SliceStable(idx.Stories, func(i, j int) bool {
		a, b := idx.Stories[i], idx.Stories[j]
		if ka, kb := sortKeys[a.ID], sortKeys[b.ID]; ka != kb {
			return ka < kb
		}
		return a.ID < b.ID
	})
	return idx, nil
}

// effectiveStoryStatus applies the parent-RFC override (validate-lib.mjs).
func effectiveStoryStatus(rfcStatus, storyStatus string) string {
	if storyStatus == "ready" && rfcStatus != "active" {
		return "draft"
	}
	return storyStatus
}

// tasksGroupBy runs a (story_id, value) query and groups it, preserving row
// order within each story — the join tables are ordered by rowid, which is the
// order the frontmatter listed them in.
func tasksGroupBy(db *sql.DB, query string) (map[string][]string, error) {
	rows, err := db.Query(query)
	if err != nil {
		return nil, fmt.Errorf("query: %w", err)
	}
	defer rows.Close()
	out := map[string][]string{}
	for rows.Next() {
		var id string
		var value sql.NullString
		if err := rows.Scan(&id, &value); err != nil {
			return nil, fmt.Errorf("scan: %w", err)
		}
		out[id] = append(out[id], value.String)
	}
	return out, rows.Err()
}

// isoMidnight renders a stored date-only string the way index.json carried it.
// Anything that is already a timestamp is passed through untouched.
func isoMidnight(v sql.NullString) string {
	d := strings.TrimSpace(v.String)
	if !v.Valid || d == "" {
		return ""
	}
	if len(d) == 10 {
		return d + "T00:00:00.000Z"
	}
	return d
}

// parseJSONArray reads one of the TEXT columns holding a JSON string array.
// A malformed value costs that one field, not the whole index.
func parseJSONArray(v sql.NullString) []string {
	if !v.Valid || strings.TrimSpace(v.String) == "" {
		return []string{}
	}
	var out []string
	if err := json.Unmarshal([]byte(v.String), &out); err != nil {
		return []string{}
	}
	return orEmpty(out)
}

// orEmpty normalises a nil slice to an empty one. index.json rendered an absent
// list as [], and the equivalence test compares the two loaders as JSON, so the
// distinction is load-bearing there even though no consumer cares.
func orEmpty(v []string) []string {
	if v == nil {
		return []string{}
	}
	return v
}

// loadTaskEventsFromDB returns the event stream, newest first, in the shape
// taskEventLinesFromJSON renders. Same rows events.json carries — this just
// skips the file.
func loadTaskEventsFromDB(path string) ([]taskEvent, error) {
	db, err := openTasksDB(path)
	if err != nil {
		return nil, err
	}
	rows, err := db.Query(`SELECT at, verb, story_id, rfc_id, pr, actor, detail
	                       FROM events ORDER BY at DESC, id DESC`)
	if err != nil {
		return nil, fmt.Errorf("query events: %w", err)
	}
	defer rows.Close()
	var out []taskEvent
	for rows.Next() {
		var (
			e                                    taskEvent
			at, verb, storyID, rfcID, actor, det sql.NullString
			pr                                   sql.NullString
		)
		if err := rows.Scan(&at, &verb, &storyID, &rfcID, &pr, &actor, &det); err != nil {
			return nil, fmt.Errorf("scan event: %w", err)
		}
		e.At = at.String
		e.Verb = verb.String
		e.Story = storyID.String
		e.RFC = rfcID.String
		e.PRRepo, e.PR = scanPRRef(pr)
		e.Actor = actor.String
		e.Detail = det.String
		out = append(out, e)
	}
	return out, rows.Err()
}
